var velen = context.rulePiece; var dead = context.sourcePiece;
if (!velen || !dead || dead.instanceId !== velen.instanceId) return { success: false, message: '' };
var player = battle.players.find(function(item) { return item.playerId === velen.ownerPlayerId; }); var removed = 0;
if (player && player.hand) player.hand.forEach(function(card) { var prophecy = card.contentState && card.contentState.velenHolyProphecy; if (prophecy && prophecy.sourcePieceId === velen.instanceId) { delete card.contentState.velenHolyProphecy; removed++; } });
var allPieces = battle.pieces.concat(battle.graveyard || []);
allPieces.forEach(function(piece) { var before = piece.statusTags ? piece.statusTags.length : 0; piece.statusTags = (piece.statusTags || []).filter(function(tag) { return !(tag.type === 'velen-fate-shelter' && tag.sourceId === velen.instanceId); }); if (piece.statusTags.length !== before && piece.rules) piece.rules = piece.rules.filter(function(rule) { return rule.id !== 'rule-velen-fate-target'; }); });
return { success: removed > 0, message: removed > 0 ? velen.name + '死亡，' + removed + '张未完预言消散' : '' };
